// Convierte las filas de la hoja `leads` en filas listas para MySQL.
// Sólo se toman los campos que el panel necesita: no copiamos la hoja
// entera para no inflar la base ni duplicar datos personales de más.
const rows = $input.all().map(i => i.json);
const now  = new Date().toISOString().slice(0, 19).replace('T', ' ');

function toMySqlDate(v) {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d) ? null : d.toISOString().slice(0, 19).replace('T', ' ');
}

const out = [];
for (const r of rows) {
  const leadId = String(r.lead_id ?? '').trim();
  if (!leadId) continue;                       // sin clave no se puede sincronizar

  out.push({ json: {
    lead_id         : leadId.slice(0, 64),
    full_name       : String(r.full_name ?? '').trim().slice(0, 160) || null,
    phone           : String(r.phone ?? '').replace(/[^0-9+]/g, '').slice(0, 32) || null,
    country         : String(r.country ?? '').trim().slice(0, 64) || null,
    language        : String(r.language ?? '').trim().slice(0, 16) || null,
    status          : String(r.status ?? '').trim().toUpperCase().slice(0, 48) || null,
    last_call_status: String(r.last_call_status ?? '').trim().toUpperCase().slice(0, 48) || null,
    call_attempts   : Number(r.call_attempts ?? 0) || 0,
    last_call_time  : toMySqlDate(r.last_call_time),
    duration_secs   : Number(r.duration_secs ?? 0) || 0,
    synced_at       : now
  }});
}

console.log(`📥 Leads normalizados para el panel: ${out.length}`);
return out;

// Convierte la hoja `conversions` (cuentas abiertas) en filas de MySQL.
const rows = $input.all().map(i => i.json);
const now  = new Date().toISOString().slice(0, 19).replace('T', ' ');

function toMySqlDate(v) {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d) ? null : d.toISOString().slice(0, 19).replace('T', ' ');
}

const out = [];
for (const r of rows) {
  const leadId = String(r.lead_id ?? '').trim();
  if (!leadId) continue;

  out.push({ json: {
    lead_id      : leadId.slice(0, 64),
    full_name    : String(r.full_name ?? '').trim().slice(0, 160) || null,
    phone        : String(r.phone ?? '').replace(/[^0-9+]/g, '').slice(0, 32) || null,
    atlantis_user: String(r.atlantis_user ?? r.username ?? '').trim().slice(0, 80) || null,
    account_id   : String(r.account_id ?? r.account ?? '').trim().slice(0, 80) || null,
    created_at   : toMySqlDate(r.created_at ?? r.timestamp ?? r.date),
    synced_at    : now
  }});
}

console.log(`📥 Cuentas normalizadas para el panel: ${out.length}`);
return out;

// Deja constancia de la sincronización. Si el panel muestra un
// "última sincronización" viejo, es señal de que WF14 dejó de correr.
const n = $input.all().length;
const now = new Date().toISOString().slice(0, 19).replace('T', ' ');
return [{ json: { rows_in: n, synced_at: now } }];
